import { StyleSheet } from 'react-native';

const styles = StyleSheet.create({
    listItem: {
        flexDirection: 'row',
        justifyContent: 'center',
        alignItems: 'center',
    },

    listText: {
        fontSize: 19,
        color: '#fff',
        backgroundColor: '#fff',
        padding: 5,
        margin: 5,
        borderRadius: 10,
    },
});
export { styles };
